-- Sample transactions for the local "admin" account (development only, never production).
-- About three months (August to 21 October 2026) of realistic spending across the five accounts
-- UBS Personal, UBS Savings (CHF), BNP Personal, BNP Savings, Revolut Personal (EUR): salary, rent,
-- groceries on both sides of the border, restaurants, subscriptions, travel, transfers.
--
-- Accounts and categories are found by name, so the script works on any local database where
-- they exist. It can run several times: rows have fixed ids starting with 5a3a1e00 and are skipped
-- when already there. The accounts' opening date moves to 1 August so the history fits.
--
-- Run (from the repository root, database container started):
--   docker exec -i orma-db psql -U orma -d orma < scripts/dev/sample-transactions.sql
-- Remove them again:
--   docker exec -i orma-db psql -U orma -d orma -c "DELETE FROM transactions WHERE id::text LIKE '5a3a1e00-%'"

BEGIN;

UPDATE accounts SET opening_date = DATE '2026-08-01', updated_at = now()
WHERE user_id = '0b9f3c1e-5d2a-4e8b-9c7f-1a2b3c4d5e6f'
  AND name IN ('UBS Personal', 'UBS Savings', 'BNP Personal', 'BNP Savings', 'Revolut Personal')
  AND opening_date > DATE '2026-08-01';

INSERT INTO transactions (
    id, user_id, account_id, amount, booked_on, merchant, category_id, note,
    original_amount, original_currency, transfer_id, version, created_at, updated_at
)
SELECT v.id::uuid, v.user_id::uuid, v.account_id, v.amount, v.booked_on, v.merchant, v.category_id,
       v.note, v.original_amount, v.original_currency, v.transfer_id::uuid, 0, now(), now()
FROM (VALUES
    ('5a3a1e00-0000-4000-8000-000000000001', '0b9f3c1e-5d2a-4e8b-9c7f-1a2b3c4d5e6f', (SELECT id FROM accounts WHERE user_id = '0b9f3c1e-5d2a-4e8b-9c7f-1a2b3c4d5e6f' AND name = 'UBS Personal'), -2150.00, DATE '2026-08-01', 'Régie du Rhône', (SELECT id FROM categories WHERE user_id = '0b9f3c1e-5d2a-4e8b-9c7f-1a2b3c4d5e6f' AND name = 'Housing'), 'Rent', NULL, NULL, NULL),
    ('5a3a1e00-0000-4000-8000-000000000002', '0b9f3c1e-5d2a-4e8b-9c7f-1a2b3c4d5e6f', (SELECT id FROM accounts WHERE user_id = '0b9f3c1e-5d2a-4e8b-9c7f-1a2b3c4d5e6f' AND name = 'UBS Personal'), -389.60, DATE '2026-08-01', 'Helsana', (SELECT id FROM categories WHERE user_id = '0b9f3c1e-5d2a-4e8b-9c7f-1a2b3c4d5e6f' AND name = 'Health'), 'Health insurance', NULL, NULL, NULL),
